      throw new Error(`Group API call failed with status: ${responseGrp.status}`);
     }

  else console.log('groups fetched sucessfully') 
   // Parse response JSON
    const data = await response.json();      // users
    const grpData = await responseGrp.json(); // groups

    // Convert users to options
    const userOptions = data.map(user => ({
      label: user.userId,
      value: [user.emailId]
    }));

    // Convert groups to options
    const grpOptions = grpData.map(group => ({
      label: group.groupId,
      value: group.users.map(user => user.emailId)
