const callCaseStatusApi = async () => {
  // Check if options exist in localStorage
  const cachedOptions = localStorage.getItem('faultCategoryOptions');
  if (cachedOptions) {
    component.data.values = JSON.parse(cachedOptions); // Use cached options
    console.log('Using cached faultCategoryOptions');
    return JSON.parse(cachedOptions);
  }
  
  const token = localStorage.getItem('keycloakToken');

  // Log error if token is not found
  if (!token) {
    console.error('Token not found in localStorage');
    return [];
  }

  const baseUrl = window.location.hostname.includes('localhost')
    ? 'http://localhost:8081'
    : localStorage.getItem('baseUrl') || '';

  try {
    const response = await fetch(`${baseUrl}/case-definition/fault-category`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
    });

    if (!response.ok) {
      throw new Error(`API call failed with status: ${response.status}`);
    }

    const data = await response.json();
    const options = data.map((item) => ({
      label: item.name,
      value: `${item.id}_${item.recommendationFlag}`,
    }));

    // Save the fetched options in localStorage
    localStorage.setItem('faultCategoryOptions', JSON.stringify(options));
    component.data.values = options; // Use the fetched options
    console.log('Fetched and saved faultCategoryOptions from API');
    return options;
  } catch (error) {
    console.error('Error calling the API:', error);
    return [];
  }
};

// Call the function to populate the options
