    const token = localStorage.getItem('keycloakToken');
    if (!token) { console.error('Token not found in localStorage'); return; }

    const urlParams = new URLSearchParams(window.location.search);
    const eventIds = urlParams.get('eventIds');
    if (!eventIds) { console.error('eventIds parameter not found in the URL'); return; }

    const baseUrl = window.location.hostname.includes('localhost')
      ? 'http://localhost:8081'
      : (localStorage.getItem('baseUrl') || '');

    const encodedEventIds = encodeURIComponent(eventIds);
    fetch(`${baseUrl}/case-definition/fault-history/eventIds?eventIds=${encodedEventIds}`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    })
    .then(response => {
      if (!response.ok) { throw new Error(`API call failed: ${response.status}`); }
      return response.json();
    })
    .then(data => {
      if (!Array.isArray(data)) return;
      const mapped = data.map(item => {
        const creationDate = item.startTime;
        const formattedDate = creationDate
          ? new Date(creationDate).toLocaleString('en-GB', {
              day: '2-digit', month: '2-digit', year: 'numeric',
              hour: '2-digit', minute: '2-digit', hour12: true
            }).replace(/\//g, '-')
          : 'Default Value';
        return {
          textField1: item.AssetDisplayName || 'Default Value',
          textField2: item.assetName || 'Default Value',
          textField3: (item.events && item.events.eventName) || 'Default Value',
          textField4: (item.eventCategory && item.eventCategory.name) || 'Default Value',
          TextFaultStartTimeDate: formattedDate,
 eventPkId: item.events.eventPkId  
   };
      });
      if (instance && typeof instance.setValue === 'function') {
        instance.setValue(mapped);
        if (typeof instance.redraw === 'function') { instance.redraw(); }
      } else {
        value = mapped;
      }
    })
    .catch(err => console.error('Error during API call:', err));
  })();
}

